CREATE OR REPLACE FUNCTION public.admin_overview() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_permission('admin.access') THEN RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501'; END IF; RETURN jsonb_build_object('registered_users',(SELECT count(*) FROM auth.users),'published_opportunities',(SELECT count(*) FROM public.opportunities o WHERE public.opportunity_is_active(o)),'draft_opportunities',(SELECT count(*) FROM public.opportunities WHERE status='draft'),'archived_opportunities',(SELECT count(*) FROM public.opportunities WHERE status='archived'),'saved_opportunities',(SELECT count(*) FROM public.saved_opportunities),'tracked_applications',(SELECT count(*) FROM public.tracked_applications)); END $$;